// Error Every error of the API. `code` is stable and is what a client tests.
// `message` is a sentence for people, in English, and may change.
// `details` is an object, empty unless the operation says what it
// holds. An error never has paths of the server, SQL or the output of a
// tool.
//
// Example: {"code":"track_unavailable","details":{},"message":"The track is not available."}
type Error struct {
	// Code The stable code. By status:
	//
	// - `400`: `invalid_request`, `invalid_cursor`, `unsupported_profile`
	// - `401`: `login_required`, `invalid_credentials`
	// - `403`: `forbidden`, `origin_not_allowed`, `request_header_required`
	// - `404`: `not_found` (no such path), `session_not_found`,
	//   `user_not_found`, `artist_not_found`, `album_not_found`,
	//   `track_not_found`, `playlist_not_found`, `item_not_found`,
	//   `track_unavailable`, `cover_not_found`, `lyrics_not_found`
	// - `405`: `method_not_allowed`
	// - `409`: `username_taken`, `last_admin`, `cannot_modify_self`
	// - `412`: `precondition_failed`
	// - `413`: `body_too_large`
	// - `421`: `host_not_allowed`
	// - `422`: `username_invalid`, `password_invalid`,
	//   `current_password_invalid`, `invalid_request`,
	//   `too_many_playlists`, `too_many_items`, `unknown_track`,
	//   `track_unavailable`, `invalid_position`
	// - `428`: `precondition_required`
	// - `500`: `internal`
	// - `503`: `not_ready`, `shutting_down`, `library_changing`
	Code ErrorCode `json:"code"`

	// Details More about the error, for a program. Empty unless the operation says otherwise.
	Details map[string]interface{} `json:"details"`

	// Message A sentence for people. Do not test it.
	Message string `json:"message"`
}

// ErrorCode The stable code. By status:
//
//   - `400`: `invalid_request`, `invalid_cursor`, `unsupported_profile`
//   - `401`: `login_required`, `invalid_credentials`
//   - `403`: `forbidden`, `origin_not_allowed`, `request_header_required`
//   - `404`: `not_found` (no such path), `session_not_found`,
//     `user_not_found`, `artist_not_found`, `album_not_found`,
//     `track_not_found`, `playlist_not_found`, `item_not_found`,
//     `track_unavailable`, `cover_not_found`, `lyrics_not_found`
//   - `405`: `method_not_allowed`
//   - `409`: `username_taken`, `last_admin`, `cannot_modify_self`
//   - `412`: `precondition_failed`
//   - `413`: `body_too_large`
//   - `421`: `host_not_allowed`
//   - `422`: `username_invalid`, `password_invalid`,
//     `current_password_invalid`, `invalid_request`,
//     `too_many_playlists`, `too_many_items`, `unknown_track`,
//     `track_unavailable`, `invalid_position`
//   - `428`: `precondition_required`
//   - `500`: `internal`
//   - `503`: `not_ready`, `shutting_down`, `library_changing`
type ErrorCode string

// Favorite A favorite track of the user. It follows the audio: `track` can
// become another track, with another id, that has the same audio, when
// MusicLib moves the track to another album; `favorited_at` stays. The
// old id can still be read with `GET /tracks/{id}`, with
// `"available": false`.
type Favorite struct {
	// FavoritedAt A moment, RFC 3339 in UTC, always with three digits of milliseconds and `Z`.
	//
	// Example: 2026-09-30T12:34:56.000Z
	FavoritedAt Timestamp `json:"favorited_at"`

	// Track A track. The id is given by Vibrance and follows the audio: it stays
	// the same when MusicLib changes the title, the number, the tags or the
	// cover, renames the album or moves it to another artist. `album` is
	// always there, with the last data known when the track is not
	// available. A track has no cover of its own: it shows `album.cover`.
	//
	//
	// Example: {"album":{"artist":{"id":"5b0c8f6e-1d2a-5e3f-9a4b-6c7d8e9f0a1b","name":"Miles Davis"},"cover":{"hash":"9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08","url":"/api/v1/albums/7d4c2f0a-3b1e-4c5d-8e9f-0a1b2c3d4e5f/cover?v=9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08"},"id":"7d4c2f0a-3b1e-4c5d-8e9f-0a1b2c3d4e5f","title":"Kind of Blue","year":1959},"artist":"Miles Davis","available":true,"disc":1,"duration_ms":562000,"favorite":false,"format":{"bit_depth":16,"bitrate":null,"channels":2,"codec":"flac","sample_rate":44100,"size":31415926},"genre":"Jazz","has_lyrics":true,"id":"0199a5c0-7b1e-7c3a-9d2f-4b6a8c0e1f23","number":1,"replay_gain":{"album_gain_db":-5.9,"album_peak":0.997,"track_gain_db":-6.48,"track_peak":0.988},"title":"So What"}
	Track Track `json:"track"`
}

// FavoriteList One page of the favorite tracks, the most recent first.
type FavoriteList struct {
	Favorites []Favorite `json:"favorites"`

	// Next The value to send as `after` to read the next page; `null` on the last page.
	//
	// Example: eyJzIjoidGl0bGUiLCJvIjoiYXNjIn0
	Next *Cursor `json:"next"`
}

// Id A UUID in its canonical form, lowercase with hyphens. An id has one spelling, in requests as in responses.
//
// Example: 0199a5c0-7b1e-7c3a-9d2f-4b6a8c0e1f23
type Id = string

// LibraryCounts The rows of the index, as they were when the last cycle began or ended.
//
// Example: {"available":412,"unavailable":3}
type LibraryCounts struct {
	Available   int64 `json:"available"`
	Unavailable int64 `json:"unavailable"`
}

// LibraryProblem One album folder the scanner could not index, or a warning about one it did.
//
// Example: {"code":"file_missing","message":"A file the receipt lists is not in the folder.","rel_path":"Miles Davis/Kind of Blue"}
type LibraryProblem struct {
	// Code A stable code. Problems, which keep the album out of the index
	// (or as it was): `receipt_missing`, `receipt_invalid`,
	// `receipt_schema_unsupported`, `receipt_too_large`, `file_missing`,
	// `file_size_mismatch`, `probe_failed`, `fingerprint_failed`,
	// `listing_failed`. Warnings, which do not: `cover_invalid`,
	// `tags_incomplete`, `lyrics_unreadable`.
	Code string `json:"code"`

	// Message A sentence for people.
	Message string `json:"message"`

	// RelPath The folder, relative to the library; empty for the library itself.
	RelPath string `json:"rel_path"`
}

// LibraryProgress How far a running cycle has come.
//
// Example: {"discovered":415,"indexed":295,"pending":120}
type LibraryProgress struct {
	// Discovered The album folders found with a valid receipt.
	Discovered int `json:"discovered"`

	// Indexed The albums this cycle has indexed.
	Indexed int `json:"indexed"`

	// Pending The albums still to index in this cycle.
	Pending int `json:"pending"`
}

// LibraryScan One cycle of the scanner that went through the library.
//
// Example: {"error":null,"finished_at":"2026-09-30T12:35:02.250Z","ok":true,"started_at":"2026-09-30T12:34:56.000Z"}
type LibraryScan struct {
	// Error Why a finished cycle is not ok, without internal details; `null` otherwise.
	Error *string `json:"error"`

	// FinishedAt `null` while the cycle runs.
	FinishedAt *Timestamp `json:"finished_at"`

	// Ok Whether the cycle went to its end. The problems of single albums do not make it false. False while the cycle runs.
	Ok bool `json:"ok"`

	// StartedAt A moment, RFC 3339 in UTC, always with three digits of milliseconds and `Z`.
	//
	// Example: 2026-09-30T12:34:56.000Z
	StartedAt Timestamp `json:"started_at"`
}

// LibraryStatus The state of the library as the scanner knows it.
//
// Example: {"albums":{"available":412,"unavailable":3},"last_scan":{"error":null,"finished_at":"2026-09-30T12:35:02.250Z","ok":true,"started_at":"2026-09-30T12:34:56.000Z"},"musiclib_maintenance":false,"problems":[{"code":"file_missing","message":"A file the receipt lists is not in the folder.","rel_path":"Miles Davis/Kind of Blue"}],"progress":null,"state":"idle","tracks":{"available":5120,"unavailable":41}}
type LibraryStatus struct {
	// Albums The rows of the index, as they were when the last cycle began or ended.
	//
	// Example: {"available":412,"unavailable":3}
	Albums LibraryCounts `json:"albums"`

	// LastScan The cycle that is running, or the last one that went through the library; `null` before the first.
	LastScan *LibraryScan `json:"last_scan"`

	// MusiclibMaintenance Whether the last cycle found the maintenance marker of MusicLib.
	MusiclibMaintenance bool `json:"musiclib_maintenance"`

	// Problems The album folders the last finished cycle could not index, and its
	// warnings, ordered by path; at most 200. The list is made again by
	// every cycle that goes through the library, and is empty after a
	// restart until the first one ends.
	Problems []LibraryProblem `json:"problems"`

	// Progress How far the running cycle has come; `null` when none is running.
	Progress *LibraryProgress `json:"progress"`

	// State - `idle`: no cycle is running.
	// - `scanning`: a cycle is running.
	// - `maintenance`: MusicLib is rebuilding or restoring its library;
	//   the index is left as it is until it ends.
	// - `unavailable`: the folder is not a MusicLib library, or the
	//   library cannot be listed; the index is left as it is.
	State LibraryStatusState `json:"state"`

	// Tracks The rows of the index, as they were when the last cycle began or ended.
	//
	// Example: {"available":412,"unavailable":3}
	Tracks LibraryCounts `json:"tracks"`
}

// LibraryStatusState - `idle`: no cycle is running.
//   - `scanning`: a cycle is running.
//   - `maintenance`: MusicLib is rebuilding or restoring its library;
//     the index is left as it is until it ends.
//   - `unavailable`: the folder is not a MusicLib library, or the
//     library cannot be listed; the index is left as it is.
type LibraryStatusState string

// LoginRequest The credentials of an account, to sign in with a cookie.
